import {useState, useEffect, useCallback, useMemo} from 'react'
import {LicenseHistory} from './LicenseHistory'
import type {LicenseChange} from '../types/license-change'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

export type LicenseHistoryResponse = {
  changes: LicenseChange[]
}

// Number of items to display per page
const PER_PAGE = 7

export function LicenseHistoryContainer() {
  const [currentPage, setCurrentPage] = useState(1)
  const [allChanges, setAllChanges] = useState<LicenseChange[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [isError, setIsError] = useState(false)
  const {basePath} = useNavigation()

  // Default endpoint if not provided as prop
  const historyEndpoint = `${basePath}/licensing/ghec/history`

  // Apply client-side pagination to the fetched data
  const {currentPageChanges, totalPages} = useMemo(() => {
    const startIndex = (currentPage - 1) * PER_PAGE
    const endIndex = startIndex + PER_PAGE
    const pageData = allChanges.slice(startIndex, endIndex)
    const calculatedTotalPages = Math.max(1, Math.ceil(allChanges.length / PER_PAGE))
    return {
      currentPageChanges: pageData,
      totalPages: calculatedTotalPages,
    }
  }, [allChanges, currentPage])

  const fetchLicenseHistory = useCallback(async () => {
    setIsLoading(true)
    setIsError(false)
    try {
      const response = await verifiedFetchJSON(historyEndpoint)
      if (response.ok) {
        const data: LicenseHistoryResponse = await response.json()
        setAllChanges(data.changes || [])
        // Reset to first page when new data is loaded
        setCurrentPage(1)
      } else {
        setIsError(true)
        setAllChanges([])
      }
    } catch {
      setIsError(true)
      setAllChanges([])
    } finally {
      setIsLoading(false)
    }
  }, [historyEndpoint])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchLicenseHistory()
  }, [fetchLicenseHistory])

  return (
    <LicenseHistory
      changes={currentPageChanges}
      isError={isError}
      isFetching={isLoading}
      currentPage={currentPage}
      totalPages={totalPages}
      onPageChange={setCurrentPage}
    />
  )
}
